// 기사면 상단 네비게이션 호출 articleHeader.setScroll(); $(window).scroll(function() { var currY = $(this).scrollTop(); var postHeight = $(this).height(); var scrollHeight = $('body').height(); var scrollPercent = (currY / (scrollHeight - postHeight)) * 100; $('.aht-bar').css('width', scrollPercent +"%"); }); 이전 기사보기 다음 기사보기 임택수 음성군수 후보, 금왕읍서 선거사무소 개소... "음성의 새로운 100년 열겠다" 바로가기 복사하기 본문 글씨 줄이기 본문 글씨 키우기 스크롤 이동 상태바 충북 임택수 음성군수 후보, 금왕읍서 선거사무소 개소... "음성의 새로운 100년 열겠다" “30년 정통 행정 전문가의 출사표, "일자리가 넘치는 첨단산업 중심도시 조성" 다짐 기자명 남난우 기동취재부 기자 입력 2026.04.20 12:02 댓글 0 다른 공유 찾기 바로가기 본문 글씨 키우기 본문 글씨 줄이기 이 기사를 공유합니다 페이스북(으)로 기사보내기 트위터(으)로 기사보내기 URL복사(으)로 기사보내기 닫기 ▲국민의힘 음성군수 후보 임택수 선거사무소 개소식 [남난우 기동취재부 기자] 국민의힘 임택수 음성군수 후보가 19일 선거사무소 개소식을 열고 본격적인 세를 과시하며 선거운동에 돌입했다. 임 후보는 금왕읍에 군수 캠프가 차려진 것은 이번이 처음이라는 점을 강조하며, 지역 균형 발전과 도약을 향한 더 큰 책임감을 느낀다고 밝혔다. 임 후보는 바쁜 일정 속에서도 개소식을 찾아준 내외빈과 당원동지, 지지자, 그리고 음성군민들에게 깊은 감사를 전하며, 이번 개소식을 단순한 선거 캠프의 시작이 아닌 "음성의 새로운 길을 열고 미래 100년을 여는 출발점"으로 규정했다. ▲국민의힘 음성군수 후보 임택수 음성에서 나고 자라 고향에서 꿈을 키워온 임 후보는 지난 30여 년간 중앙과 지방 행정 현장을 두루 섭렵한 정통 행정 전문가다. 40대 초반 청와대 행정관을 거쳐 행정안전부, 국토교통부 등 핵심 중앙부처에서 일했으며, 충청북도 재난안전실장, 음성부군수, 청주시 부시장 등을 역임하며 국정과 지역 행정에 대한 폭넓은 경험과 탄탄한 인적 네트워크를 구축해 왔다. "어떠한 순간에도 '사람 중심'이라는 신념으로 현장의 목소리를 먼저 듣고 군민의 삶을 먼저 살폈습니다. 저는 인기에만 영합하고 단기 성과에 머무는 군정을 하지 않겠습니다. 다음 세대가 '그때 음성의 방향이 제대로 바뀌었다'고 기억할 수 있는 책임 있는 군정을 펼치겠습니다.“ 임 후보는 음성이 산업단지와 기업, 혁신도시, 그리고 사통팔달의 교통망까지 성장의 기반을 고루 갖춘 큰 가능성의 도시라고 평가했다. 이어 이제는 그 가능성을 현실로 만들어 군민의 실질적인 삶의 변화로 연결해야 할 때라고 강조하며, 음성을 '일자리가 넘치는 첨단산업 중심도시'로 키우겠다는 핵심 비전을 제시했다. 구체적인 실천 방안으로 반도체와 첨단산업의 전략적 유치, 기업하기 좋은 도시 조성을 통해 지역경제에 새로운 활력을 불어넣겠다고 밝혔다. 아울러 아이 키우기 좋은 교육도시, 청년이 돌아오는 도시, 어르신이 편안하고 군민이 자부심을 느끼는 도시를 만들겠다는 청사진도 함께 제시했다. 그는 "교육은 경쟁력이 되어야 하고, 농업은 안정된 소득으로 이어져야 하며, 안전은 그 어떤 정책보다 먼저 지켜져야 한다"고 역설하며, 스포츠와 문화, 레저 산업 역시 지역에 활력을 불어넣는 새로운 성장 동력으로 육성하겠다고 덧붙였다. "음성의 미래는 기다린다고 오지 않습니다. 누군가는 앞장서 방향을 세우고, 책임지고, 끝까지 해내야 합니다. 덩치만 큰 음성이 아니라, 변화에 더 잘 대응하는 단단하고 품격 있으며, 진정 사람이 살 만한 음성을 만들겠습니다.“ 마지막으로 임 후보는 결과로 증명하는 군정, 군민이 편안하도록 공정하고 바른 군정을 이끌겠다고 약속했다. 준비된 군수로서 음성의 새로운 100년을 여는 일에 모든 힘을 쏟겠으며, 군민들이 "음성에 사는 것이 자랑스럽다"고 말씀하실 수 있도록 4년을 8년처럼 뛰겠다고 다짐했다. 이어 "말보다 실천으로, 성과로, 내일을 만들어 가겠다"며 결연한 의지로 인사말을 마무리했다. 남난우 기동취재부 기자 namwoo97@hanmail.net 저작권자 © IPN뉴스 무단전재 및 재배포 금지 SNS 기사보내기 공유 이메일 기사저장 $(document).ready(function(e) { $('.scrap-btn').on('click', function(e) { var idxno = $(this).data('idxno'); if(confirm("기사를 스크랩 하시겠습니까?")){ $.ajax({ type: 'post', dataType: 'json', url: '/news/articleScrap.ajax.php', data: {'tp':'A', 'idxno':idxno}, success: function(data) { alert(data[1]); }, error: function(error, request) { alert('error!!!'); console.log("code:"+request.status+"\n"+"message:"+request.responseText+"\n"+"error:"+error); } }); } }); }); 이 시각 추천뉴스 #skin-29 > .item:not(:first-child) {margin-top:12px} '모두의 카드' 9월까지 더 돌려받는다…환급 기준액 50% 인하 한국 유조선, 우회로 '홍해' 통과…호르무즈 봉쇄 이후 처음 이중언어 역량을 인증받는 기회, 제11회 이중언어능력인증시험 개최 음성군, 충북도민체육대회 개·폐회식 완성도 높인다...‘연출자문위원회’ 개최 장으로 향하는 의료관광의 문, 부산 전문 통역 인재 양성 본격화 "공영주차장 5부제 시행 여부, 지도앱으로 확인하세요" 손끝에서 피어나는 새로운 시작, 함평 경력단절여성 공예교실 첫걸음 #skin-30 > .item {position:relative;margin-top:16px}
