#AD159851162111.ad-template .col .ad-view { position:relative; } 김문근 전상인 국민의힘 충북 충주시장 후보로 이동석(40) 전 대통령비서실 행정관, 단양군수 후보로 김문근(69) 현 군수, 옥천군수 후보로 전상인(57) 국회의원 보좌관이 선출됐다. 국민의힘 충북도당 공천관리위원회는 22일 충주시·단양군·옥천군 단체장 경선 결과를 발표했다. 충주시장 경선에서 이 전 행정관은 정용근 전 충북경찰청장과 대결에서 승리했다. 단양군수 경선에서는 김 군수가 오영탁 충북도의원에 승리하며 재선 도전에 나서게 됐다. 옥천군수 경선에서는 전 보좌관이 김승룡 전 옥천문화원장에게 승리하며 본선에 진출했다. 후보자별 득표율은 규정에 따라 공개되지 않았다. 이번 경선(결선) 투표는 지난 20~21일 치러졌으며 책임당원 50%와 일반국민 여론조사 50%를 합산해 결과를 도출했다. 이날 국민의힘 기초단체장 3곳의 후보가 선출되면서 민주당과 9곳의 대진표가 확정됐다. 충주시장은 맹정섭 전 민주당 충주시지역위원장과 국힘 이동석 전 대통령비서실 행정관이 맞붙는다. 단양군수는 민주당 김광직 전 단양군의원이 김문근 현 군수에게 도전장을 던졌다. 옥천군수는 민주당 전상인 국회의원 보좌관이 황규철 현 군수에게 도전하게 됐다. 이밖에 괴산군수는 선거는 민주당 이차영 전 군수와 국민의힘 송인헌 현 군수가 4년 만에 다시 맞붙는 전·현직 리턴매치가 성사됐다. 증평군수는 민주당 현직인 이재영 군수에게 이민표 전 괴산군 농업건설국장이, 음성군수는 민주당 현직인 조병옥 군수에 임택수 전 청주부시장이 각각 도전하는 구도다. 또 보은군수는 국민의힘 현직인 최재형 군수에게 하유정 전 충북도의원이, 영동군수는 국민의힘 현직인 정영철 군수에 이수동 영동군의원이 도전장을 던졌다. 진천군수는 민주당 김명식 정책위 부의장과 국민의힘 이양섭 충북도의장이 맞붙게 됐다. 아직 대진표가 완성되지 않은 충북지사, 청주시장, 제천시장의 경우 민주당은 이미 후보자를 확정했다. 민주당은 충북지사에 신용한 대통령직속 지방시대위원회 부위원장을, 청주시장에 이장섭 전 국회의원을, 제천시장에 이상천 전 시장을 각각 선출했다. 반면 국민의힘은 3곳 모두 후보자 전원을 대상으로 예비경선을 실시, 이를 통과한 후보 1명과 현직 단체장 간 일대일 경선을 치르는 이른바 ‘한국시리즈’로 최종후보자를 선출하면서 경선일정 늦어지고 있다. 충북지사 본경선은 김영환 현 지사와 윤갑근 전 국민의힘 충북도당위원장 간 25~26일 실시, 27일 최종후보자가 발표된다. 청주시장은 예비경선을 통과한 서승우 전 국민의힘 충북도당위원장과 이범석 현 시장이 오는 28일 토론회에 이어 29~30일 본경선을 치른 뒤 내달 1일 최종후보자를 발표한다. 제천시장은 이재우 전 기획재정부 총사업비관리과장과 이충형 전 중앙당 대변인이 24~25일 예비결선을 진행한 뒤 승자가 내달 1~2일 김창규 현 시장과 본경선 치른다. 이어 다음 달 3일 최종 후보를 선출할 예정이다. 충청매일 CCDN SNS 기사보내기 페이스북(으)로 기사보내기 네이버블로그(으)로 기사보내기 URL복사(으)로 기사보내기 이메일(으)로 기사보내기 다른 공유 찾기 기사스크랩하기 $(document).ready(function(e) { $('.scrap-btn').on('click', function(e) { var idxno = $(this).data('idxno'); if(confirm("기사를 스크랩 하시겠습니까?")){ $.ajax({ type: 'post', dataType: 'json', url: '/news/articleScrap.ajax.php', data: {'tp':'A', 'idxno':idxno}, success: function(data) { alert(data[1]); }, error: function(error, request) { alert('error!!!'); console.log("code:"+request.status+"\n"+"message:"+request.responseText+"\n"+